export class CodecMonitor{_peerConnection;_visited=!0;timestamp;id;payloadType;transportId;mimeType;clockRate;channels;sdpFmtpLine;attachments;appData;constructor(t,e){this._peerConnection=t,this.id=e.id,this.timestamp=e.timestamp,this.mimeType=e.mimeType,Object.assign(this,e)}get visited(){const t=this._visited;return this._visited=!1,t}accept(t){this._visited=!0;t.timestamp-this.timestamp<=0||Object.assign(this,t)}getPeerConnection(){return this._peerConnection}getIceTransport(){return this._peerConnection.mappedIceTransportMonitors.get(this.transportId??"")}createSample(){return{id:this.id,timestamp:this.timestamp,payloadType:this.payloadType,transportId:this.transportId,mimeType:this.mimeType,clockRate:this.clockRate,channels:this.channels,sdpFmtpLine:this.sdpFmtpLine,attachments:this.attachments}}}